// src/components/CategoryButton.js

import React, { useState } from 'react';

// This is the recursive component that creates the tree structure.
// It takes a single category object as a prop.
function CategoryButton({ category }) {
    // CORRECT: Place the useState hook at the very top of the function, before any conditional logic.
    const [isExpanded, setIsExpanded] = useState(false);

    // A guard clause to prevent runtime errors if the category prop is null or undefined.
    if (!category) {
        return null;
    }

    // A helper function to toggle the expansion state.
    const toggleExpand = () => {
        setIsExpanded(!isExpanded);
    };

    // Check if the category has children.
    const hasChildren = category.children && category.children.length > 0;

    return (
        <div style={{ marginLeft: '20px' }}>
            {/* The main button for the category */}
            <button
                onMouseDown={toggleExpand}
                style={{
                    padding: '5px 5pz',
                    fontSize: '8px',
                    margin: '5px',
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '5px',
                    cursor: 'pointer',
                }}
            >
                {/* Use a simple arrow to indicate expand/collapse */}
                {hasChildren ? (isExpanded ? '▼ ' : '▶ ') : ''}
                {category.name}
            </button>

            {/* Conditionally render the children if the button is expanded */}
            {isExpanded && hasChildren && (
                <div style={{ display: 'flex', flexDirection: 'column' }}>
                    {category.children.map(child => (
                        // Recursively call the CategoryButton component for each child
                        <CategoryButton key={child.id} category={child} />
                    ))}
                </div>
            )}
        </div>
    );
}

export default CategoryButton;
